function calendarEventReadyMarker(className, title, body, experimentId, start, end, blockId, lane, laneCount) { const detail = encodeURIComponent(JSON.stringify({ title: title, body: body })); const experimentAttr = experimentId ? ' data-calendar-experiment="' + experimentId + '"' : ''; const blockAttr = blockId ? ' data-calendar-block="' + blockId + '"' : ''; const startDate = start ? new Date(start) : null; const endDate = end ? new Date(end) : null; const hour = startDate ? startDate.getHours() + startDate.getMinutes() / 60 : 8; const duration = startDate && endDate ? Math.max(.5, (endDate - startDate) / 3600000) : .5; const top = Math.max(0, Math.min(24, hour)) * 56; const height = Math.max(24, Math.min(24, duration) * 56); const style = startDate ? ' style="top:' + top + 'px;height:' + height + 'px;--event-lane:' + (lane || 0) + ';--event-lanes:' + (laneCount || 1) + '"' : ''; const experiment = experimentId ? state.experiments.find(x => x.id === experimentId) : null; const tooltip = experiment ? experimentLabel(experiment) : title; const safeTooltip = String(tooltip).replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); const ready = className.includes('ready-marker'); const visibleTitle = ready ? "<span class=\"ready-icon\" aria-hidden=\"true\">✓</span>" + escapeHtml(title) : escapeHtml(title); const visibleBody = escapeEventBody(body); return '<div class="calendar-event ' + className + '" data-calendar-detail="' + detail + '"' + experimentAttr + blockAttr + style + ' title="' + safeTooltip + '" aria-label="' + safeTooltip + '"><strong>' + visibleTitle + '</strong><span class="event-body">' + visibleBody + '</span></div>'; }
function calendarEvent(className, title, body, experimentId, start, end, blockId, lane, laneCount) { return calendarEventReadyMarker(className, title, body, experimentId, start, end, blockId, lane, laneCount); }

function detailStageEstimate(exp, index) {
  const currentIndex = exp.stages.findIndex(stage => stage.status === "current");
  if (index < currentIndex) return null;
  let cursor = currentIndex >= 0 && exp.stages[currentIndex].startedAt ? new Date(exp.stages[currentIndex].startedAt) : null;
  let targetStart = null;
  for (let i = currentIndex; i <= index; i += 1) {
    const stage = exp.stages[i];
    if (!stage) continue;
    if (i === currentIndex) { targetStart = stage.startedAt ? new Date(stage.startedAt) : null; if (stage.readyAt) cursor = new Date(stage.readyAt); }
    else if (i > currentIndex) {
      const start = stage.plannedStartAt ? new Date(stage.plannedStartAt) : cursor ? new Date(cursor.getTime() + DEFAULT_TRANSITION_HOURS * 3600000) : null;
      if (i === index) targetStart = start;
      cursor = start && stage.duration ? new Date(start.getTime() + calendarStageHours(stage, exp) * 3600000) : start;
    } else if (cursor && stage.duration) cursor = new Date(cursor.getTime() + calendarStageHours(stage, exp) * 3600000);
  }
  return targetStart && !Number.isNaN(targetStart.getTime()) ? targetStart : null;
}
function detailModal(id, focusStageName) {
  const e = state.experiments.find(x => x.id === id);
  const normalizedFocus = String(focusStageName || '').trim().toLowerCase();
  if (!e) return;
  const current = e.stages.find(x => x.status === "current");
  const currentIndex = current ? e.stages.indexOf(current) : -1;
  const next = current ? e.stages[currentIndex + 1] : null;
  const nextPlan = next?.plannedStartAt ? escapeHtml(next.name) + " · " + fmtDateTime(next.plannedStartAt) : next ? escapeHtml(next.name) + " · System suggestion" : "—";
  const workflow = e.stages.map((s, index) => {
    const isCurrent = s.status === "current";
    const estimate = isCurrent && s.readyAt ? new Date(s.readyAt) : detailStageEstimate(e, index);    const isFocused = normalizedFocus && s.name.trim().toLowerCase() === normalizedFocus;
    const locationHint = s.location ? "<span class=\"stage-location-hint\">" + escapeHtml(s.location) + "</span>" : "";
    const displayEstimate = s.plannedStartAt ? new Date(s.plannedStartAt) : estimate; const timeHint = isCurrent && s.startedAt ? "Started<br>" + fmtDateTime(s.startedAt) : displayEstimate ? "Estimated<br>" + fmtDateTime(displayEstimate) : s.status === "completed" ? "Done" : "";
    return '<div class="stage ' + s.status + (isCurrent ? " is-current" : "") + (isFocused ? " is-focused" : "") + '"><span class="stage-dot">' + (s.status === "completed" ? "✓" : "") + '</span><div class="stage-info"><strong>' + escapeHtml(s.name) + '</strong><span>' + (s.duration ? (s.duration >= 1 ? s.duration + " h" : Math.round(s.duration * 60) + " min") + (isMeasurementStage(s) ? " / sample" : "") : "Duration variable") + '</span>' + locationHint + '</div><span class="stage-time">' + timeHint + '</span></div>';
  }).join("");
  const isFinalMeasurement = current && currentIndex === e.stages.length - 1 && isMeasurementStage(current); const startsMeasurement = next && isMeasurementStage(next); const actions = current ? '<div class="detail-actions-heading">Edit</div><div class="detail-actions-row"><button type="button" class="secondary-button" id="editStartButton">Start time</button>' + (next ? '<button type="button" class="secondary-button" id="editPlannedTimeButton">Plan time</button>' : '<span></span>') + '</div><div class="detail-action-divider"></div><button class="primary-button" id="completeButton">' + (isFinalMeasurement ? "Done" : startsMeasurement ? "Start measurement" : "Complete current step") + '</button>' : "";
  const readyBox = isMeasurementStage(current) ? '<div><span>Action</span><strong>Complete measurement</strong></div>' : next?.plannedStartAt ? "" : '<div><span>Ready</span><strong>' + (currentReadyAt(e) ? fmtDateTime(currentReadyAt(e)) : "When you finish") + '</strong></div>';
  const plannedBox = next?.plannedStartAt ? '<div><span>Next planned start</span><strong>' + nextPlan + '</strong></div>' : "";
  const locationMeta = current?.location ? '<span class="meta-chip">·</span><span class="meta-chip">' + escapeHtml(current.location) + '</span>' : "";
  const locationBox = current?.location ? '<div><span>Location</span><strong>' + escapeHtml(current.location) + '</strong></div>' : "";
  openModal('<div class="detail-head"><div><h2 id="modalTitle">' + escapeHtml(e.template) + '</h2><div class="detail-meta"><span class="meta-chip">' + escapeHtml(Array.isArray(e.samples) ? e.samples.join(", ") : (e.batch || "Samples")) + '</span>' + locationMeta + '</div>' + (e.details ? '<p class="subtle experiment-details">' + escapeHtml(e.details) + '</p>' : '') + '</div><button class="close" aria-label="Close">×</button></div><div class="workflow">' + workflow + '</div><div class="current-box"><span class="eyebrow">Current stage</span><div class="current-grid"><div><span>Started</span><strong>' + (current?.startedAt ? fmtDateTime(current.startedAt) : "—") + '</strong></div>' + readyBox + '' + plannedBox + locationBox + '</div><div class="detail-footer">' + (current ? '<div class="detail-actions">' + actions + '</div>' : '') + '<button class="secondary-button" id="deleteButton">Delete</button></div></div>');
  if (!current) { const currentBox = document.querySelector(".current-box"); const deleteFooter = document.createElement("div"); deleteFooter.className = "detail-footer"; deleteFooter.innerHTML = "<button class=\"secondary-button\" id=\"deleteButton\">Delete<\/button>"; currentBox?.replaceWith(deleteFooter); }
  document.getElementById("completeButton")?.addEventListener("click", () => completeChoice(id));
  document.getElementById("editStartButton")?.addEventListener("click", () => editStartTimeModal(id));
  document.getElementById("editPlannedTimeButton")?.addEventListener("click", () => editAllPlannedTimesInDetail(id));
  document.getElementById("deleteButton").onclick = () => deleteExperiment(id);
}

function detailTimeInputValue(value) {
  const date = value instanceof Date ? value : new Date(value);
  const pad = number => String(number).padStart(2, "0");
  const hour24 = date.getHours();
  return pad(date.getMonth() + 1) + "/" + pad(date.getDate()) + " " + pad(hour24 % 12 || 12) + ":" + pad(date.getMinutes()) + " " + (hour24 >= 12 ? "PM" : "AM");
}
function editAllPlannedTimesInDetail(id) {
  const e = state.experiments.find(x => x.id === id);
  if (!e) return;
  const currentIndex = e.stages.findIndex(stage => stage.status === "current");
  if (currentIndex < 0) return;
  const stageNodes = Array.from(document.querySelectorAll(".workflow .stage"));
  const editable = e.stages.map((stage, index) => ({ stage, index })).filter(item => item.index > currentIndex);
  if (!editable.length) return;
  stageNodes.forEach(node => node.classList.remove("is-focused"));
  editable.forEach(({ stage, index }) => {
    const node = stageNodes[index];
    const timeNode = node?.querySelector(".stage-time");
    if (!timeNode) return;
    const estimate = stage.plannedStartAt ? new Date(stage.plannedStartAt) : detailStageEstimate(e, index);
    const inputId = "planStageTime" + index;
    timeNode.innerHTML = '<label class="inline-plan-label" for="' + inputId + '">Plan start</label><input class="inline-plan-time" id="' + inputId + '" data-plan-stage-index="' + index + '" type="text" inputmode="text" maxlength="15" placeholder="MM/DD HH:mm AM/PM" value="' + (estimate ? detailTimeInputValue(estimate) : "") + '" />';
    setupLabTimeInput(inputId);
    if (estimate) {
      const input = document.getElementById(inputId);
      input.value = detailTimeInputValue(estimate);
      input.dispatchEvent(new Event("input", { bubbles: true }));
    }
  });
  const detailActions = document.querySelector(".detail-actions");
  if (!detailActions) return;
  detailActions.innerHTML = '<div class="detail-actions-heading">Plan time</div><div class="detail-plan-note">Edit the planned start time for each upcoming step.</div><div class="detail-actions-row"><button type="button" class="secondary-button" id="cancelPlanTimesButton">Cancel</button><button type="button" class="primary-button" id="savePlanTimesButton">Save planned times</button></div>';
  document.getElementById("cancelPlanTimesButton").onclick = () => detailModal(id);
  document.getElementById("savePlanTimesButton").onclick = () => {
    editable.forEach(({ stage, index }) => {
      const input = document.getElementById("planStageTime" + index);
      if (!input || !input.value.trim()) return;
      const when = parseLabTime(readLabTime(input.id));
      if (!Number.isNaN(when.getTime())) stage.plannedStartAt = when.toISOString();
    });
    save();
    closeModal();
    render();
    detailModal(id);
  };
}
